"use client";

import { lazy, Suspense, useSyncExternalStore } from "react";

const emptySubscribe = () => () => undefined;

const Scene = lazy(() => import("./scene"));

/** Wire a route to this file after install. WebGL loads only in the browser. */
export default function ChatCardPage() {
  const mounted = useSyncExternalStore(
    emptySubscribe,
    () => true,
    () => false
  );
  if (!mounted) {
    return <div className="h-dvh w-full bg-background" />;
  }
  return (
    <Suspense fallback={<div className="h-dvh w-full bg-background" />}>
      <Scene />
    </Suspense>
  );
}

"use client";

import { Canvas, useFrame, useThree } from "@react-three/fiber";
import { IfInSessionMode, useXR, XR } from "@react-three/xr";
import { type RefObject, useCallback, useRef, useState } from "react";
import type { Group } from "three";
import {
  type CardSize,
  cardMeters,
  placeAtGaze,
  WorldCard,
  WorldThemeProvider,
} from "@/components/ui/world-card";
import { ChatCardBody, ChatCardProvider, useChatSession } from "./chat-body";
import { ExperienceHud } from "./hud";
import { ORB_RADIUS, SpeakingOrb } from "./speaking-orb";
import { xrStore } from "./xr-store";

const CHAT_CARD = {
  w: 340,
  h: 520,
  minW: 280,
  minH: 400,
  maxW: 800,
  maxH: 720,
};
const ORB_LIFT = 0.08;
const DESKTOP_POS: [number, number, number] = [0, 1.52, -0.35];

function appearanceFromDom(): "light" | "dark" {
  if (typeof document === "undefined") {
    return "dark";
  }
  return document.documentElement.classList.contains("dark") ? "dark" : "light";
}

function Studio({ appearance }: { appearance: "light" | "dark" }) {
  const major = appearance === "dark" ? 0x4b5158 : 0xc9cdd3;
  const minor = appearance === "dark" ? 0x2c3036 : 0xe2e4e8;
  const floor = appearance === "dark" ? "#1a1d21" : "#eeeff1";
  return (
    <>
      <color attach="background" args={[floor]} />
      <mesh position={[0, 0, 0]} rotation={[-Math.PI / 2, 0, 0]}>
        <planeGeometry args={[12, 12]} />
        <meshStandardMaterial color={floor} />
      </mesh>
      <gridHelper args={[8, 32, major, minor]} />
    </>
  );
}

function ChatDock() {
  const session = useXR((s) => s.session);
  const camera = useThree((s) => s.camera);
  const [open, setOpen] = useState(true);
  const [size, setSize] = useState<CardSize>({
    w: CHAT_CARD.w,
    h: CHAT_CARD.h,
  });
  const meters = cardMeters(size);
  const orbTop = meters.h / 2 + ORB_LIFT;
  const orbLift = useRef(0);
  const orbSlot = useRef<Group>(null);
  const dragging = useRef(false);
  const anchor = useRef<Group>(null);
  const placedSession = useRef(false);
  const placedDesktop = useRef(false);

  const bringHere = useCallback(() => {
    const a = anchor.current;
    if (!a) {
      return;
    }
    placeAtGaze(a, camera, {
      distance: 0.55,
      drop: 0.25,
      side: 0.18,
      face: true,
    });
    placedSession.current = true;
  }, [camera]);

  useFrame((_, dt) => {
    const a = anchor.current;
    if (!a) {
      return;
    }
    if (session) {
      placedDesktop.current = false;
      if (!placedSession.current) {
        bringHere();
      }
    } else if (!placedDesktop.current) {
      a.position.set(...DESKTOP_POS);
      a.rotation.set(0, 0, 0);
      placedDesktop.current = true;
      placedSession.current = false;
    }
    const orbGoal = open ? orbTop : 0;
    orbLift.current += (orbGoal - orbLift.current) * Math.min(1, 10 * dt);
    if (orbSlot.current) {
      orbSlot.current.position.y = orbLift.current;
    }
  });

  const toggleCard = () => {
    if (dragging.current) {
      return;
    }
    setOpen((value) => !value);
  };

  return (
    <WorldCard
      ref={anchor}
      handle={open}
      limits={CHAT_CARD}
      movable
      onDragEnd={() => {
        dragging.current = false;
      }}
      onDragStart={() => {
        dragging.current = true;
      }}
      onSizeChange={setSize}
      radius={ORB_RADIUS}
      resizable={open}
      shape={open ? "card" : "orb"}
      size={size}
    >
      <ChatCardProvider>
        <ChatCardSlot
          onToggle={toggleCard}
          open={open}
          orbSlot={orbSlot}
          size={size}
        />
      </ChatCardProvider>
    </WorldCard>
  );
}

function ChatCardSlot({
  onToggle,
  open,
  orbSlot,
  size,
}: {
  onToggle: () => void;
  open: boolean;
  orbSlot: RefObject<Group | null>;
  size: CardSize;
}) {
  const { streaming } = useChatSession();
  return (
    <>
      <group ref={orbSlot}>
        <SpeakingOrb onClick={onToggle} speaking={streaming} />
      </group>
      {open ? <ChatCardBody height={size.h} width={size.w} /> : null}
    </>
  );
}

export default function ChatCardScene() {
  const appearance = appearanceFromDom();

  return (
    <div className="relative h-dvh w-full overflow-hidden bg-background">
      <ExperienceHud />
      <Canvas
        camera={{
          fov: 70,
          near: 0.01,
          far: 50,
          position: [0, 1.6, 0.15],
          rotation: [0, 0, 0],
        }}
        gl={{ antialias: true, alpha: true }}
        style={{ position: "absolute", inset: 0, touchAction: "none" }}
      >
        <XR store={xrStore}>
          <hemisphereLight args={[0xffffff, 0xb8bcc2, 0.95]} />
          <directionalLight intensity={1.35} position={[0.55, 1.6, 0.45]} />
          <WorldThemeProvider appearance={appearance}>
            <IfInSessionMode deny="immersive-ar">
              <Studio appearance={appearance} />
            </IfInSessionMode>
            <ChatDock />
          </WorldThemeProvider>
        </XR>
      </Canvas>
    </div>
  );
}

import { createXRStore } from "@react-three/xr";

const CURSOR_OFFSET = 0.001;

const rightRay = {
  minDistance: 0.02,
  rayModel: { opacity: 0.55, color: "#e4e4e7" },
  cursorModel: {
    opacity: 0.9,
    size: 0.006,
    color: "#2563eb",
    cursorOffset: CURSOR_OFFSET,
  },
};

const hands = {
  model: true,
  grabPointer: true,
  touchPointer: true,
  rayPointer: {
    minDistance: 0.02,
    rayModel: { opacity: 0.4, color: "#e4e4e7", maxLength: 1.2 },
    cursorModel: {
      opacity: 0.85,
      size: 0.005,
      color: "#2563eb",
      cursorOffset: CURSOR_OFFSET,
    },
  },
} as const;

export const xrStore = createXRStore({
  foveation: 0.5,
  offerSession: false,
  bounded: true,
  hitTest: false,
  domOverlay: false,
  anchors: false,
  meshDetection: false,
  planeDetection: false,
  depthSensing: false,
  bodyTracking: false,
  handTracking: true,
});

function applyARInput() {
  xrStore.setController(
    { model: false, rayPointer: false, grabPointer: false },
    "left"
  );
  xrStore.setController(
    { model: false, rayPointer: rightRay, grabPointer: true },
    "right"
  );
  xrStore.setHand(hands, "left");
  xrStore.setHand(hands, "right");
}

function applyVRInput() {
  xrStore.setController(
    { model: true, rayPointer: false, grabPointer: true },
    "left"
  );
  xrStore.setController(
    { model: true, rayPointer: rightRay, grabPointer: true },
    "right"
  );
  xrStore.setHand(hands, "left");
  xrStore.setHand(hands, "right");
}

export function enterAR() {
  applyARInput();
  return xrStore.enterAR();
}

export function enterVR() {
  applyVRInput();
  return xrStore.enterVR();
}

"use client";

import { useChat } from "@ai-sdk/react";
import { Container, Text } from "@react-three/uikit";
import { isTextUIPart, isToolUIPart } from "ai";
import { createContext, type ReactNode, useContext, useMemo } from "react";
import { VrChatInput } from "@/components/ui/vr-chat-input";
import { asciiSafe, VrMarkdown } from "@/components/ui/vr-markdown";
import { VrReasoning } from "@/components/ui/vr-reasoning";
import { VrTool } from "@/components/ui/vr-tool";
import { VrWorked } from "@/components/ui/vr-worked";
import { splitWorkedParts } from "@/components/ui/worked";
import { useWorldTheme } from "@/components/ui/world-card";
import {
  type CardChatMessage,
  chatTransport,
  initialChatMessages,
} from "./lib/chat-transport";

type ChatSession = {
  busy: boolean;
  messages: CardChatMessage[];
  send: (text: string) => void;
  streaming: boolean;
};

const ChatSessionContext = createContext<ChatSession | null>(null);

export function ChatCardProvider({ children }: { children: ReactNode }) {
  const { messages, sendMessage, status } = useChat<CardChatMessage>({
    throttle: 50,
    messages: initialChatMessages,
    transport: chatTransport,
  });
  const streaming = status === "streaming";
  const busy = streaming || status === "submitted";
  const value = useMemo<ChatSession>(
    () => ({
      busy,
      messages,
      send: (text) => {
        void sendMessage({ text });
      },
      streaming,
    }),
    [busy, messages, sendMessage, streaming]
  );
  return (
    <ChatSessionContext.Provider value={value}>
      {children}
    </ChatSessionContext.Provider>
  );
}

export function useChatSession() {
  const session = useContext(ChatSessionContext);
  if (!session) {
    throw new Error("useChatSession must be used under ChatCardProvider");
  }
  return session;
}

type CardPart = CardChatMessage["parts"][number];

function toolNameOf(part: CardPart) {
  if ("toolName" in part && typeof part.toolName === "string") {
    return part.toolName;
  }
  if (part.type.startsWith("tool-")) {
    return part.type.slice(5);
  }
  return part.type;
}

function VrPart({
  isStreaming,
  part,
}: {
  isStreaming?: boolean;
  part: CardPart;
}) {
  const theme = useWorldTheme();
  if (isTextUIPart(part) && part.text) {
    if (isStreaming || part.state === "streaming") {
      return (
        <Text color={theme.text} fontSize={13}>
          {asciiSafe(part.text)}
        </Text>
      );
    }
    return <VrMarkdown markdown={part.text} />;
  }
  if (part.type === "reasoning" && "text" in part && part.text) {
    return (
      <VrReasoning
        isStreaming={
          Boolean(isStreaming) ||
          ("state" in part && part.state === "streaming")
        }
        text={part.text}
      />
    );
  }
  if (part.type === "dynamic-tool" || isToolUIPart(part)) {
    return (
      <VrTool
        input={"input" in part ? part.input : undefined}
        output={"output" in part ? part.output : undefined}
        toolName={toolNameOf(part)}
      />
    );
  }
  return null;
}

function VrAssistantParts({
  isStreaming,
  message,
}: {
  isStreaming: boolean;
  message: CardChatMessage;
}) {
  const duration = isStreaming
    ? undefined
    : message.metadata?.responseTime
      ? Math.round(message.metadata.responseTime / 1000)
      : undefined;
  return (
    <Container flexDirection="column" flexShrink={0} gap={8} width="100%">
      {splitWorkedParts(message.parts ?? []).map((segment) => {
        if (segment.kind === "worked") {
          const start = segment.items[0]?.index ?? 0;
          return (
            <VrWorked
              duration={duration}
              isStreaming={isStreaming}
              key={`w-${start}`}
            >
              {segment.items.map((item) => (
                <VrPart
                  isStreaming={isStreaming}
                  key={item.index}
                  part={item.part}
                />
              ))}
            </VrWorked>
          );
        }
        return (
          <VrPart
            isStreaming={isStreaming}
            key={segment.item.index}
            part={segment.item.part}
          />
        );
      })}
    </Container>
  );
}

function MessageRow({
  isStreaming,
  message,
}: {
  isStreaming: boolean;
  message: CardChatMessage;
}) {
  const mine = message.role === "user";
  const theme = useWorldTheme();
  const text = message.parts
    .filter(isTextUIPart)
    .map((part) => part.text)
    .join("\n");
  if (mine && !text) {
    return null;
  }
  return (
    <Container
      alignItems={mine ? "flex-end" : "flex-start"}
      flexDirection="column"
      flexShrink={0}
      width="100%"
    >
      {mine ? (
        <Container
          alignSelf="flex-end"
          backgroundColor={theme.bubble}
          borderRadius={10}
          flexShrink={0}
          maxWidth="80%"
          padding={8}
          width="auto"
        >
          <Text color={theme.text} fontSize={13}>
            {asciiSafe(text)}
          </Text>
        </Container>
      ) : (
        <Container flexShrink={0} maxWidth="100%" width="100%">
          <VrAssistantParts isStreaming={isStreaming} message={message} />
        </Container>
      )}
    </Container>
  );
}

export function ChatCardBody({
  width,
  height,
}: {
  width: number;
  height: number;
}) {
  const theme = useWorldTheme();
  const { busy, messages, send, streaming } = useChatSession();
  const streamingId =
    streaming && messages.at(-1)?.role === "assistant"
      ? (messages.at(-1)?.id ?? null)
      : null;

  return (
    <Container
      backgroundColor={theme.card}
      borderRadius={12}
      flexDirection="column"
      gap={6}
      height={height}
      padding={8}
      pixelSize={0.001}
      pointerEvents="auto"
      width={width}
    >
      <Text color={theme.text} fontSize={14}>
        Assistant
      </Text>
      <Container
        backgroundColor={theme.border}
        flexShrink={0}
        height={1}
        width="100%"
      />
      <Container
        flexDirection="column"
        flexGrow={1}
        gap={6}
        minHeight={0}
        overflow="scroll"
        width="100%"
      >
        {messages.map((message) => (
          <MessageRow
            isStreaming={streamingId === message.id}
            key={message.id}
            message={message}
          />
        ))}
      </Container>
      <Container
        backgroundColor={theme.border}
        flexShrink={0}
        height={1}
        width="100%"
      />
      <VrChatInput
        disabled={busy}
        onSubmit={send}
        placeholder={busy ? "Working..." : "Ask the assistant"}
      />
    </Container>
  );
}

"use client";

import { useFrame } from "@react-three/fiber";
import { useRef } from "react";
import type { Mesh } from "three";
import { useWorldTheme } from "@/components/ui/world-card";

export const ORB_RADIUS = 0.04;

export function SpeakingOrb({
  onClick,
  speaking = false,
}: {
  onClick: () => void;
  speaking?: boolean;
}) {
  const mesh = useRef<Mesh>(null);
  const theme = useWorldTheme();

  useFrame((state) => {
    const m = mesh.current;
    if (!m) {
      return;
    }
    const t = state.clock.elapsedTime;
    const s = speaking
      ? 1 + Math.sin(t * 8) * 0.08
      : 1 + Math.sin(t * 2.2) * 0.04;
    m.scale.setScalar(s);
  });

  return (
    <mesh ref={mesh} name="speaking-orb" onClick={onClick}>
      <icosahedronGeometry args={[ORB_RADIUS, 2]} />
      <meshStandardMaterial
        color={theme.card}
        emissive={theme.hover}
        emissiveIntensity={0.45}
        metalness={0.2}
        roughness={0.35}
      />
    </mesh>
  );
}

export type AIMetadata = {
  createdAt?: string;
  status?: "pending" | "success" | "error";
  responseTime?: number;
};

import { createChat } from "@shadcn/helpers/ai-sdk";
import type { UIMessage } from "ai";
import type { AIMetadata } from "./ai-types";

export type CardChatMessage = UIMessage<AIMetadata>;

const galleryChat = createChat<CardChatMessage>()
  .user("What am I looking at?")
  .assistant(({ writer }) => {
    writer.stepStart();
    writer.reasoning(
      "The wearer is in a VR session. I will describe the card in the scene, not a 2D page."
    );
    writer.sleep(900);
    writer.stepStart();
    writer.text(
      `You are looking at a **VR** chat card.

- Drag the handle to move it
- Pinch a corner to resize
- Enter VR or AR to place it at your gaze`
    );
  })
  .user("Make the hole 8mm.")
  .assistant(({ writer }) => {
    writer.stepStart();
    writer.reasoning(
      "They want the hole at 8 mm. I will call cad_edit, then keep the answer visible on the card."
    );
    writer
      .tool("cad_edit", {
        dynamic: true,
        input: { feature: "hole", diameter_mm: 8 },
      })
      .sleep(1400)
      .output({ ok: true, diameter_mm: 8 });
    writer.stepStart();
    writer.text(
      `Updated the hole to **8 mm**. The card stays in the scene while the model rebuilds.

| Feature | Size |
| --- | --- |
| hole | 8 mm |`
    );
  });

const ASSISTANT_RESPONSE_MS = [4200, 6800];

let assistantIndex = -1;

export const initialGalleryMessages = galleryChat.get().map((message) => {
  if (message.role !== "assistant") {
    return message;
  }
  assistantIndex += 1;
  return {
    ...message,
    metadata: {
      createdAt: message.metadata?.createdAt ?? "2026-06-24T12:00:00.000Z",
      status: message.metadata?.status ?? "success",
      ...message.metadata,
      responseTime:
        message.metadata?.responseTime ?? ASSISTANT_RESPONSE_MS[assistantIndex],
    },
  };
});

export const galleryChatTransport = galleryChat.transport({
  delayMs: 80,
  fallback: ({ writer, messages }) => {
    const assistantTurns = messages.filter(
      (message) => message.role === "assistant"
    ).length;
    const variants = [
      () => {
        writer.stepStart();
        writer.reasoning(
          "They asked from the card. I will describe grab and resize, then mention Enter VR."
        );
        writer.sleep(800);
        writer.stepStart();
        writer.text(
          "Drag the **handle** under the card to move it. Pinch a **corner** to resize. On a Quest, Enter VR or AR and the card sits at your gaze."
        );
      },
      () => {
        writer.stepStart();
        writer.reasoning(
          "Follow-up looks like another model edit. I will run cad_edit again so the card still shows a tool fold."
        );
        writer
          .tool("cad_edit", {
            dynamic: true,
            input: { feature: "fillet", radius_mm: 1 },
          })
          .sleep(1200)
          .output({ ok: true, radius_mm: 1 });
        writer.stepStart();
        writer.text(
          "Added a **1 mm** fillet. Say if you want the hole changed too."
        );
      },
      () => {
        writer.stepStart();
        writer.reasoning(
          "This is a restock-style aside. There is no inventory in this scene. I will say so and stay on the card."
        );
        writer.sleep(700);
        writer.stepStart();
        writer.text(
          "This example is a VR chat card, not an inventory app. Ask about the card, or point `chat-transport.ts` at your own API."
        );
      },
    ] as const;
    const writeFallback =
      variants[assistantTurns % variants.length] ?? variants[0];
    writeFallback();
  },
});

/**
 * Default install uses a mocked transport (no model).
 * Point a live transport at your own API when you have one:
 *
 *   import { DefaultChatTransport } from "ai";
 *   export const chatTransport = new DefaultChatTransport({ api: "/api/chat" });
 *   export const initialChatMessages = undefined;
 */
export {
  type CardChatMessage,
  galleryChatTransport as chatTransport,
  initialGalleryMessages as initialChatMessages,
} from "./mock-chat-messages";

"use client";

import { useEffect, useState } from "react";
import { enterAR, enterVR } from "./xr-store";

type XrSupport = { ar: boolean; vr: boolean; ready: boolean };

function SessionButton({
  enabled,
  label,
  onEnter,
}: {
  enabled: boolean;
  label: string;
  onEnter: () => void;
}) {
  return (
    <button
      className="h-9 rounded-lg px-3 text-sm disabled:cursor-not-allowed disabled:opacity-40"
      disabled={!enabled}
      onClick={() => {
        if (enabled) {
          onEnter();
        }
      }}
      title={enabled ? label : "Needs a headset (Quest Browser)"}
      type="button"
    >
      {label}
    </button>
  );
}

export function ExperienceHud() {
  const [support, setSupport] = useState<XrSupport>({
    ar: false,
    vr: false,
    ready: false,
  });

  useEffect(() => {
    const xr = navigator.xr;
    if (!xr) {
      setSupport({ ar: false, vr: false, ready: true });
      return;
    }
    let cancelled = false;
    Promise.all([
      xr.isSessionSupported("immersive-ar").catch(() => false),
      xr.isSessionSupported("immersive-vr").catch(() => false),
    ]).then(([ar, vr]) => {
      if (!cancelled) {
        setSupport({ ar, vr, ready: true });
      }
    });
    return () => {
      cancelled = true;
    };
  }, []);

  const xrReady = support.ready && (support.ar || support.vr);

  return (
    <div className="pointer-events-auto absolute top-4 right-4 z-10 flex max-w-[min(100%-2rem,28rem)] flex-col items-end gap-2">
      <p className="rounded-lg border border-border bg-card/95 px-3 py-2 text-muted-foreground text-xs shadow-lg">
        Drag the handle to move. Corners and edges resize.
        {support.ready && !xrReady
          ? " Enter VR/AR needs a headset (Quest Browser)."
          : null}
      </p>
      <div className="flex flex-wrap justify-end gap-1 rounded-xl border border-border bg-card/95 p-1 shadow-lg">
        <SessionButton
          enabled={support.vr}
          label="Enter VR"
          onEnter={() => {
            enterVR();
          }}
        />
        <SessionButton
          enabled={support.ar}
          label="Enter AR"
          onEnter={() => {
            enterAR();
          }}
        />
      </div>
    </div>
  );
}
